### 3️⃣ Frontend: request paid content through the API

```tsx
// pages/protected.tsx
import { createClient } from '@supabase/supabase-js';
import { useEffect, useState } from 'react';
import { useSession } from '@supabase/auth-helpers-react';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

export default function Protected() {
  const { data: session } = useSession();
  const [loading, setLoading] = useState(true);
  const [content, setContent] = useState<string | null>(null);

  useEffect(() => {
    if (!session) return;
    fetch('/api/protected-content')
      .then((res) => {
        if (res.ok) return res.json();
        throw new Error('Not allowed');
      })
      .then((data) => setContent(data.content))
      .catch(() => setContent(null));
    setLoading(false);
  }, [session]);

  if (loading) return <p>Loading…</p>;
  if (!content) return <p>You need a Pro plan to see this.</p>;

  return <div dangerouslySetInnerHTML={{ __html: content }} />;
}
```

**Server‑side route (`pages/api/protected-content.js`):**

```js
// pages/api/protected-content.js
import { createClient } from '@supabase/supabase-js';

export default async function handler(req, res) {
  const supabase = createClient(
    process.env.SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE!
  );

  const { user } = req.body; // send from fetch headers or session
  if (!user) return res.status(401).json({ error: 'unauthenticated' });

  const { data: profile, error } = await supabase
    .from('profiles')
    .select('is_pro')
    .eq('id', user.id)
    .single();

  if (error || !profile?.is_pro)
    return res.status(403).json({ error: 'pro only' });

  // return the protected content
  res.json({ content: '<p>Secret pro content here...</p>' });
}
```

> **Why?**  
> The API route checks the database and returns data only if `is_pro` is true. The browser can’t “invent” a super‑user.

